"""Original vector landscape artwork; no third-party game imagery."""
from pathlib import Path
out=Path(__file__).resolve().parents[1]/'site/assets'
out.mkdir(exist_ok=True)
palettes={'embers':('#b7aa7d','#52615d','#182b32','#d9b46c'),'forest':('#b8cbb0','#567c68','#193e39','#c7dca8'),'orbit':('#51657c','#233448','#0d1c2c','#ebcda3'),'neon':('#8a6a91','#354f69','#172731','#e5a78a'),'snow':('#c6d6d8','#889fa8','#3b5668','#f5ebcf')}
for name,(sky,middle,front,light) in palettes.items():
    towers=''.join(f'<path d="M{x} 430v-{h}h24v{h}z M{x-5} {430-h}l17-42 17 42z" fill="{front}" opacity=".8"/>' for x,h in [(500,150),(550,230),(600,190),(650,100)])
    trees=''.join(f'<path d="M{x} {y}l-22 60h44z M{x} {y+25}l-30 70h60z M{x-3} {y+60}h6v75h-6z" fill="{front}" opacity=".8"/>' for x,y in [(90,330),(160,380),(930,340),(1020,290),(1100,355),(820,400)])
    stars=''.join(f'<circle cx="{i*97%1200}" cy="{i*37%290}" r="1.4" fill="{light}" opacity=".6"/>' for i in range(70)) if name in ['orbit','neon'] else ''
    svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 760"><defs><linearGradient id="s" x2="0" y2="1"><stop stop-color="{sky}"/><stop offset="1" stop-color="{middle}"/></linearGradient><radialGradient id="sun"><stop stop-color="{light}" stop-opacity=".6"/><stop offset="1" stop-color="{light}" stop-opacity="0"/></radialGradient><filter id="grain"><feTurbulence type="fractalNoise" baseFrequency=".7" numOctaves="3" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".12"/></feComponentTransfer></filter></defs><path fill="url(#s)" d="M0 0h1200v760H0z"/><circle cx="820" cy="180" r="340" fill="url(#sun)"/><circle cx="820" cy="180" r="58" fill="{light}" opacity=".75"/>{stars}<path d="M0 400L170 170 330 390 440 270 590 400 760 260 930 390 1100 170 1200 280V760H0z" fill="{middle}"/><path d="M0 480L230 340 380 470 520 390 720 460 900 340 1200 480V760H0z" fill="{front}" opacity=".52"/>{towers}<path d="M0 600Q180 420 400 570T800 540T1200 490V760H0z" fill="{front}" opacity=".72"/>{trees}<path d="M0 690Q160 570 400 660T800 610T1200 600V760H0z" fill="{front}"/><path d="M470 760Q450 650 610 560T670 450Q790 560 650 650L620 760" fill="{light}" opacity=".18"/><g transform="translate(810 550)"><circle cy="-56" r="13" fill="#101b21"/><path d="M-10-40L-35 25 23 24 13-38z" fill="#101b21"/><path d="M-12 20l-6 51h10l10-47 9 47h10L15 20z" fill="#101b21"/><path d="M25-20l12 66" stroke="{light}" stroke-width="3"/></g><path d="M0 0h1200v760H0z" filter="url(#grain)" opacity=".65"/><text x="1135" y="735" text-anchor="end" font-family="sans-serif" font-size="12" letter-spacing="4" fill="{light}" opacity=".7">BW / ORIGINAL DEMO ART</text></svg>'''
    (out/f'{name}.svg').write_text(svg,encoding='utf-8')
